def calculate_total(items, promo_code=None):
    # Prototype with float drift and no rule families
    subtotal = 0.0
    for item in items:
        subtotal += item['qty'] * item['unit_price']
    if promo_code == 'SAVE10':
        subtotal = subtotal * 0.9
    return round(subtotal * 1.1, 2)

