from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP
from typing import Iterable, Optional

CENT = Decimal('0.01')
ZERO = Decimal('0.00')


def money(value) -> Decimal:
    return Decimal(str(value)).quantize(CENT, rounding=ROUND_HALF_UP)


class PricingRule:
    name: str = 'rule'


@dataclass(frozen=True)
class VolumeTierRule(PricingRule):
    tiers: tuple
    name: str = 'volume_tier'

    def discount_for(self, items: list, subtotal: Decimal) -> tuple[Decimal, Optional[str]]:
        total_qty = sum(int(i['qty']) for i in items)
        best_rate = Decimal('0')
        best_min = 0
        for min_qty, rate in self.tiers:
            if total_qty >= min_qty and min_qty >= best_min:
                best_min = min_qty
                best_rate = Decimal(str(rate))
        if best_rate <= 0:
            return ZERO, None
        return (subtotal * best_rate).quantize(CENT, rounding=ROUND_HALF_UP), f'volume:{best_min}'


@dataclass(frozen=True)
class PromoCodeRule(PricingRule):
    code: str
    discount_type: str
    value: Decimal
    stackable: bool = False

    def discount_for(self, base: Decimal) -> Decimal:
        val = Decimal(str(self.value))
        if self.discount_type == 'percent':
            return (base * val).quantize(CENT, rounding=ROUND_HALF_UP)
        if self.discount_type == 'fixed':
            return val.quantize(CENT, rounding=ROUND_HALF_UP)
        raise ValueError(f'Unknown discount_type: {self.discount_type}')


@dataclass(frozen=True)
class TaxRule(PricingRule):
    rate: Decimal
    name: str = 'tax'

    def tax_for(self, taxable: Decimal) -> Decimal:
        if taxable <= ZERO:
            return ZERO
        return (taxable * Decimal(str(self.rate))).quantize(CENT, rounding=ROUND_HALF_UP)


class PricingEngine:
    def __init__(self, rules: Iterable[PricingRule]):
        self.rules = list(rules)

    def quote(self, items: list, promo_codes: Optional[Iterable[str]] = None) -> dict:
        codes = set(promo_codes or [])
        subtotal = sum((Decimal(str(i['unit_price'])) * int(i['qty']) for i in items), Decimal('0'))
        subtotal = subtotal.quantize(CENT, rounding=ROUND_HALF_UP)
        applied = []

        vol_discount = ZERO
        for r in self.rules:
            if isinstance(r, VolumeTierRule):
                d, label = r.discount_for(items, subtotal)
                if label:
                    vol_discount += d
                    applied.append(label)
        vol_discount = min(subtotal, vol_discount)
        after_vol = subtotal - vol_discount

        stackable_rules = [r for r in self.rules if isinstance(r, PromoCodeRule) and r.code in codes and r.stackable]
        non_stackable_rules = [r for r in self.rules if isinstance(r, PromoCodeRule) and r.code in codes and not r.stackable]

        stack_sum = sum((r.discount_for(after_vol) for r in stackable_rules), ZERO)
        best_non_stack = None
        best_non_stack_amt = ZERO
        for r in non_stackable_rules:
            amt = r.discount_for(after_vol)
            if amt > best_non_stack_amt:
                best_non_stack_amt = amt
                best_non_stack = r

        if best_non_stack is not None and best_non_stack_amt >= stack_sum:
            promo_discount = min(after_vol, best_non_stack_amt)
            if promo_discount > ZERO:
                applied.append(f'promo:{best_non_stack.code}')
        else:
            promo_discount = min(after_vol, stack_sum)
            for r in stackable_rules:
                if r.discount_for(after_vol) > ZERO:
                    applied.append(f'promo:{r.code}')

        discount_total = (vol_discount + promo_discount).quantize(CENT, rounding=ROUND_HALF_UP)
        taxable = max(ZERO, subtotal - discount_total)
        tax_total = ZERO
        for r in self.rules:
            if isinstance(r, TaxRule):
                t = r.tax_for(taxable)
                if t > ZERO:
                    tax_total += t
                    applied.append(r.name)
        tax_total = tax_total.quantize(CENT, rounding=ROUND_HALF_UP)
        total = (taxable + tax_total).quantize(CENT, rounding=ROUND_HALF_UP)
        return {
            'subtotal': subtotal,
            'discount_total': discount_total,
            'tax_total': tax_total,
            'total': total,
            'applied_rules': applied,
        }


def calculate_total(items, promo_code=None):
    rules = [
        PromoCodeRule('SAVE10', 'percent', Decimal('0.10'), stackable=False),
        TaxRule(Decimal('0.10')),
    ]
    codes = [promo_code] if promo_code else []
    return PricingEngine(rules).quote(items, codes)['total']
